package com.northstarbank.console.service;import com.northstarbank.console.domain.*;import java.time.Instant;import java.util.Map;import org.springframework.web.client.RestClient;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component class WorkflowJobs{private final FinancialRepository financial;private final AuditRepository audit;private final PolicyRepository policy;private final RestClient routes;WorkflowJobs(FinancialRepository f,AuditRepository a,PolicyRepository p,RestClient.Builder b){financial=f;audit=a;policy=p;routes=b.build();}@Scheduled(cron="0 15 1 * * *",zone="Europe/London")@Transactional void expireRequests(){Instant cutoff=Instant.now().minusSeconds(7*86400);String route=policy.findById(1L).map(p->p.escalationEndpoint).orElse(null);for(FinancialRequest r:financial.findTop50ByStatusOrderByRequestedAtAsc("pending_approval")){if(r.requestedAt.isBefore(cutoff)){r.status="expired";audit.save(new AuditEvent("SYSTEM","FINANCIAL_EXPIRED","financial_request",1,r.customerId,"scheduled","seven_day_expiry","pending_approval","expired"));
  if(route!=null&&route.startsWith("http"))routes.post().uri(java.net.URI.create(route)).body(Map.of("event","financial_request_expired","requestId",r.id,"branch",r.owningBranch,"amount",r.amount)).retrieve().toBodilessEntity();}}}}
